import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Alchemy","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/alchemy.md","filePath":"en/guide/professions/alchemy.md"}'),s={name:"en/guide/professions/alchemy.md"};function o(l,e,n,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="alchemy" tabindex="-1">Alchemy <a class="header-anchor" href="#alchemy" aria-label="Permalink to &quot;Alchemy&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Explore material reactions to make useful preparations.</li><li><a href="/Syrolands-Public/en/guide/characters/skills.html">Skill</a>, learned <a href="/Syrolands-Public/en/guide/characters/techniques.html">techniques</a> and execution matter alongside the formula.</li><li>Medical mixtures, smoke, toxins and materials give alchemists expedition and trading roles.</li></ul><p><span id="at-a-glance"></span><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span><span id="magic-materials"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Prepare</td><td>Crush, dissolve, heat, distill, separate and combine.</td></tr><tr><td>Observe</td><td>Record reactions in an Alchemical Journal; turn observations into understood formulations.</td></tr><tr><td>Use or trade</td><td>Make oils, salves, powders, inks, solvents, reagents and volatile mixtures.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Reagents and a crafting menu produce familiar potions.</td><td>Processes and discoverable reactions shape formulations.</td></tr><tr><td>Healing, cure, poison and explosion potions already provide field utility.</td><td>Broader preparations could connect medicine, smoke, adhesives and other crafts.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/alchemy/" target="_blank" rel="noreferrer">Alchemy</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An analgesic could temporarily reduce pain penalties without repairing the underlying trauma. Its medical effects and counterplay remain undecided.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Distillation and Toxicology are possible learned paths. Purity, stability and material quality affect the result.</li><li>Copying a recipe does not copy its maker’s <a href="/Syrolands-Public/en/guide/glossary.html#mastery">mastery</a>. Reagent recipes remain undecided, and carried materials can be looted.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Spell materials</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/alchemy.html">Alchemy</a></p>',18)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
